def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    pressure_scores = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            score = 0.0
            if bid is not None:
                score += float(bid)
            if opp.get('no_water_days', 0) >= 1:
                score += 12.0
            if opp.get('hp', 0) <= 4:
                score += 10.0
            if opp.get('budget', 0) < DAILY_SALARY:
                score -= 8.0
            if prev.get('status') in ('dead', 'eliminated', 'error'):
                score -= 20.0
            pressure_scores.append(score)

    if not alive:
        return float(min(budget, 12.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    opp_pressure = max(pressure_scores) if pressure_scores else 0.0

    supply_tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_tightness < 0:
        supply_tightness = 0.0
    if supply_tightness > 1:
        supply_tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 38.0
    elif hp <= 4:
        urgency += 24.0
    elif hp <= 6:
        urgency += 12.0

    if no_water >= 2:
        urgency += 34.0
    elif no_water >= 1:
        urgency += 18.0

    urgency += supply_tightness * 18.0

    if day >= 8:
        urgency += 8.0

    base = 18.0 + urgency

    if highest_prev >= 120:
        target = min(highest_prev * 0.72, 92.0) + urgency * 0.25
    elif highest_prev >= 80:
        target = max(42.0, highest_prev * 0.78) + urgency * 0.22
    elif highest_prev >= 45:
        target = max(30.0, avg_prev * 0.92 + 4.0) + urgency * 0.18
    else:
        target = base + max(0.0, opp_pressure * 0.08)

    rich_threats = 0
    for opp in alive:
        if opp.get('budget', 0) > budget and opp.get('hp', 0) > 4:
            rich_threats += 1
    target += 3.0 * rich_threats

    if supply >= 23 and hp >= 6 and no_water == 0:
        target *= 0.72
    elif supply <= 17:
        target *= 1.18

    reserve_floor = DAILY_SALARY * 0.22
    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget - min(reserve_floor, budget * 0.15))

    if hp <= 2 or no_water >= 2:
        target = max(target, min(budget, 78.0))

    if target < 0:
        target = 0.0

    bid = min(budget, target)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] < 5:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max_prev * 0.95)

    return min(my_status['budget'], DAILY_SALARY * 0.7)
